    "section": "Связь с логотерапией",
    "text": "Парадоксальная интенция логична в рамках логотерапии: она меняет не столько симптом, сколько **позицию человека к своему страху и страданию**, возвращая ему внутреннюю свободу и ощущение ответственности за собственную реакцию.\n\nМетод не подменяет работу со смыслом, а служит практическим инструментом освобождения от невротического круга, чтобы человек мог снова обращаться к ценностям и поиску смысла.",
