    "id": "authors/frankl/three-sources-of-meaning.md#Смысл жизни у Франкла",
    "title": "Три источника смысла по Франклу",
    "sourcePath": "authors/frankl/three-sources-of-meaning.md",
    "section": "Смысл жизни у Франкла",
    "text": "Виктор Франкл считал, что смысл жизни человек не придумывает произвольно, а **обнаруживает во внешнем мире** и в своей позиции к обстоятельствам. Терапевт не «даёт» готовый смысл, а помогает пациенту услышать собственную совесть и увидеть возможности смысла.\n\nСостояние, когда стремление к смыслу фрустрировано, Франкл называл **экзистенциальным вакуумом** — внутренней пустотой, которая может вести к ноогенным неврозам, апатии и депрессии.",
