    "id": "authors/jung/archetypes.md#Коллективное бессознательное",
    "title": "Архетипы и коллективное бессознательное",
    "sourcePath": "authors/jung/archetypes.md",
    "section": "Коллективное бессознательное",
    "text": "Карл Юнг считал, что психика включает не только сознание и личное бессознательное, но и более глубокий слой — **коллективное бессознательное**, общее для всех людей.\n\nКоллективное бессознательное не формируется из личного опыта, а является наследуемым и универсальным слоем психики, в котором содержатся архетипы. Это духовное наследие человечества, задающее типичные мотивы переживаний, сновидений, мифов и культурных образов.",
