    "sourcePath": "authors/jung/archetypes.md",
    "section": "Как формируется Тень",
    "text": "По мере социализации ребёнок усваивает, что «хорошо» и что «плохо», и постепенно отказывается от тех проявлений, которые окружение не принимает. Неприемлемые черты вытесняются из сознания и образуют Тень.\n\n**Состав Тени:**\n- **Личное содержание:** личный опыт, травмы, стыд\n- **Коллективное содержание:** архетипические образы «зла», преступника, демона",
