    "section": "Зачем работать с Тенью",
    "text": "**Индивидуация** — цель развития личности по Юнгу: становление целостным, уникальным «Я», где сознательное и бессознательное в диалоге. Принятие и интеграция Тени — ключевой этап.\n\n**Результаты работы с Тенью:**\n- Снижение внутреннего напряжения, чувства вины и стыда\n- Осознание реальных мотивов, потребностей и границ\n- Перевод разрушительной энергии в конструктивные формы\n- Меньше осуждения других (снижается потребность проецировать)\n\nВажно: речь не о том, чтобы «изжить» Тень, а о том, чтобы осознать её, признать и найти ей место в структуре личности.",
