    "id": "authors/jung/archetypes.md#Простые шаги для начинающих",
    "title": "Архетипы и коллективное бессознательное",
    "sourcePath": "authors/jung/archetypes.md",
    "section": "Простые шаги для начинающих",
    "text": "### 1. Наблюдение за проекциями\n\nОбратите внимание, какие качества в других вас особенно раздражают или восхищают — часто это подсказка к содержанию собственной Тени.\n\n**Вопрос к себе:** «Где во мне есть хоть немного того, что я так не люблю / так идеализирую в других?»\n\n### 2. Работа со снами\n\nЮнг считал сны прямым выражением работы архетипов. Вести дневник снов, выписывать повторяющихся персонажей, размышлять, что в них похоже на вас.\n\n### 3. Честный самоанализ\n\nПисать «некрасивые списки»: чего я стыжусь, чего боюсь в себе, какие мысли никогда бы не озвучил вслух.\n\n### 4. Безопасные границы\n\nС тяжёлыми теневыми материалами лучше работать с профессиональным психологом / юнгианским аналитиком.",
