    "id": "authors/jung/shadow.md#Что такое Тень",
    "title": "Тень",
    "sourcePath": "authors/jung/shadow.md",
    "section": "Что такое Тень",
    "text": "**Тень** — один из ключевых архетипов в аналитической психологии Карла Юнга, связанный с подавленными, непризнанными и социально нежелательными качествами личности.\n\nТень — это то, что человек вытесняет или не хочет признавать в себе:\n- Агрессия\n- Зависть\n- Жадность\n- Страх\n- Импульсы\n- Другие «неудобные» черты",
