    "id": "authors/jung/shadow.md#Как работает Тень",
    "title": "Тень",
    "sourcePath": "authors/jung/shadow.md",
    "section": "Как работает Тень",
    "text": "Юнг подчёркивал, что **Тень не исчезает**, а продолжает влиять на поведение, часто через **проекции на других людей**.\n\nНас особенно сильно задевают в других те качества, которые мы не разрешаем себе. Это и есть проекция Тени: мы видим в другом то, что не можем принять в себе.\n\n### Пример проекции\n\nЕсли человек подавляет собственную агрессию, он будет особенно чувствителен к агрессии окружающих и видеть её даже там, где её нет. Внешний мир становится зеркалом внутренней Тени.",
