    "section": "Тень и коллективное бессознательное",
    "text": "Темы «тёмной стороны», двойника, врага или скрытого зла так часто повторяются в мифах и культуре, потому что они выражают архетипическую работу коллективного бессознательного.\n\nТень относится к более глубоким слоям психики и рассматривается как часть общей структуры бессознательного — наряду с другими архетипами.",
