    "id": "authors/jung/shadow.md#Работа с Тенью",
    "title": "Тень",
    "sourcePath": "authors/jung/shadow.md",
    "section": "Работа с Тенью",
    "text": "Принятие Тени — важнейший шаг на пути **индивидуации** (становления целостной личностью). Пока Тень остаётся неосознанной, она управляет человеком. Когда она осознана и интегрирована — становится источником энергии и творчества.\n\n### Практические шаги\n\n- Замечать, что именно раздражает в других людях — это может быть проекцией собственной Тени\n- Вести дневник снов и фантазий\n- Использовать [активное воображение](../../practices/shadow-work.md) для диалога с Тенью",
