    "id": "authors/litvak/amortization.md#Виды амортизации",
    "title": "Метод амортизации Литвака",
    "sourcePath": "authors/litvak/amortization.md",
    "section": "Виды амортизации",
    "text": "### 1. Непосредственная амортизация\n\nМгновенное согласие прямо по ходу разговора.\n\n**Пример:**\n- «Вы сегодня ужасно выглядите!»\n- «Да, вы правы, сегодня не лучший мой день».\n\n### 2. Отставленная амортизация\n\nКогда в моменте вы сорвались или не смогли ответить, а позже возвращаетесь с письмом или разговором.\n\n**Пример:** «Вчера вы назвали меня глупцом, я обиделся. Сейчас понимаю, что вы, возможно, правы — действительно бываю глупцом. Критикуйте меня чаще, это помогает развиваться».\n\n### 3. Профилактическая амортизация\n\nЗаранее заданный тон и стиль общения (самоирония, открытая готовность признать свои ошибки), снижающие вероятность будущих конфликтов.",
