    "id": "authors/litvak/amortization.md#Основные принципы",
    "title": "Метод амортизации Литвака",
    "sourcePath": "authors/litvak/amortization.md",
    "section": "Основные принципы",
    "text": "Литвак описывает ряд правил амортизационного общения:\n\n1. **Спокойно принимать комплименты** — не обесценивать и не смущаться, а признавать их\n2. **Соглашаться с первого раза** — если предложение устраивает, без лишних «кокетств» и торгов\n3. **Не навязывать свои услуги** — помогать после того, как сделали свои дела\n4. **Предлагать сотрудничество один раз** — не уговаривать: «уговаривать — значит насиловать»\n5. **Критиковать себя самому** — не ждать, пока начнут критиковать",
