    "text": "### Оскорбление или хамство\n\n**А:** «Ты козёл / идиот / глупец!»\n\n**Б (амортизация):** «Вы абсолютно правы!» или «Как вы догадались?» — спокойно, без сарказма.\n\n### Манипулятивные комплименты\n\n**А:** «Вы такой талантливый, без вас проект не получится, помогите срочно сегодня же!»\n\n**Б:** «Спасибо за горячие комплименты, они мне особенно приятны, раз вы говорите это бескорыстно и без скрытых просьб» — дальше спокойный отказ или перенос помощи.\n\n### Эмоциональные обвинения\n\n**А:** «Ты эгоист, думаешь только о себе!»\n\n**Б:** «Да, я часто думаю о себе, тут вы правы. И при этом мне важно, чтобы и тебе было хорошо — давай обсудим, что именно тебя задело».",
