    "sourcePath": "authors/mindell/dreambody.md",
    "section": "Что такое Dreambody",
    "text": "Арнольд Минделл заметил, что если усиливать и исследовать телесные симптомы (напряжения, боли, непроизвольные движения), они начинают разворачиваться в те же образы и темы, которые появляются в ночных сновидениях.\n\nНа этом основании он ввёл понятие **dreambody** — «сновидящего тела» или «тела сновидения».\n\n**Dreambody** — это процесс, который одновременно проявляется как:\n- Телесные ощущения и симптомы\n- Ночные сновидения\n\nТо есть **тело и сновидение — два зеркальных проявления одного и того же**.\n\nDreambody можно переживать как энергетическое поле или «тонкое тело», которое посылает сигналы по разным каналам — через симптомы, сновидения, фантазии, движения, необычные состояния, — направляя внимание к тому, что хочет осознаться.",
