    "section": "1. Наблюдение (без оценки)",
    "text": "Описываем факты ситуации — как на видеозаписи, без ярлыков и обобщений. Смысл в том, чтобы другой человек не почувствовал критику или обвинение и не ушёл в оборону.\n\n**Пример:** вместо «Ты всегда опаздываешь» — «Сегодня ты пришёл в 10:30, хотя мы договаривались на 10:00».",
