    "section": "2. Чувство",
    "text": "Называем свои реальные чувства, а не мысли и обвинения. В ННО чувства понимаются как «сигналы» о том, удовлетворены наши потребности или нет.\n\n**Пример:** «Я чувствую раздражение и усталость» — это чувство. А «Я чувствую, что ты меня не уважаешь» — уже интерпретация и скрытое обвинение.",
