    "text": "Типичное ННО-сообщение можно собрать в одну фразу:\n\n> «Когда я вижу, что ты пришёл в 10:30, хотя мы договаривались на 10:00 **(наблюдение)**, я чувствую раздражение и напряжение **(чувства)**, потому что мне важно пунктуально использовать общее время **(потребность)**. Ты мог бы в следующий раз написать, если задерживаешься? **(просьба)**»\n\nПо этой же схеме можно не только говорить о себе, но и эмпатически «угадывать» чувства и потребности собеседника, проверяя свои предположения.",
