    "id": "authors/wilber/aqal-four-quadrants.md#Что такое AQAL",
    "title": "AQAL-модель: четыре квадранта",
    "sourcePath": "authors/wilber/aqal-four-quadrants.md",
    "section": "Что такое AQAL",
    "text": "**AQAL** — акроним от «all quadrants, all levels, all lines, all states, all types» («все квадранты, все уровни, все линии, все состояния, все типы»).\n\nЭто базовая матрица интегрального подхода Кена Уилбера: любое явление (человек, организация, событие) рассматривается сразу по нескольким измерениям, а не через одну «любимую» теорию.\n\nУилбер использует AQAL как мета-теорию, объединяющую психологию, духовные традиции, социологию, нейронауки и другие дисциплины в единую обобщающую карту.",
