    "id": "authors/wilber/aqal-four-quadrants.md#Четыре квадранта",
    "title": "AQAL-модель: четыре квадранта",
    "sourcePath": "authors/wilber/aqal-four-quadrants.md",
    "section": "Четыре квадранта",
    "text": "У модели два пересекающихся измерения: **«внутреннее/внешнее»** и **«индивидуальное/коллективное»**. В результате получаются 4 фундаментальные перспективы на реальность.\n\n| Квадрант | Обозначение | Смысл |\n|----------|-------------|-------|\n| **Верхний левый** | **I** (индивидуальное внутреннее) | Субъективный опыт личности: мысли, чувства, намерения, смыслы |\n| **Верхний правый** | **It** (индивидуальное внешнее) | Наблюдаемое поведение, тело, мозг, физиология, действия |\n| **Нижний левый** | **We** (коллективное внутреннее) | Культура, ценности, общие смыслы, «мы-чувство», коллективные мифы |\n| **Нижний правый** | **Its** (коллективное внешнее) | Социальные системы и институты, экономика, технологии, экосистемы |\n\n**Идея Уилбера:** любую ситуацию — депрессию человека, организационный кризис или общественный конфликт — нужно рассматривать сразу во всех четырёх квадрантах. Иначе картина будет неполной, а решения — однобокими.",
