    "id": "authors/wilber/aqal-four-quadrants.md#Уровни сознания (Spiral Dynamics)",
    "title": "AQAL-модель: четыре квадранта",
    "sourcePath": "authors/wilber/aqal-four-quadrants.md",
    "section": "Уровни сознания (Spiral Dynamics)",
    "text": "Уилбер опирается на модель **Spiral Dynamics** (Грейвз–Бек–Коэн), интерпретируя её как уровни ценностей и сознания. Каждый следующий уровень «превосходит и включает» предыдущий (transcend and include).\n\n- **Бежевый** — выживание, базовые инстинкты\n- **Фиолетовый** — магическое племенное сознание, защита клана\n- **Красный** — импульсивная сила, власть, «я беру, что хочу»\n- **Синий** — порядок, закон, «одна правильная истина», традиционная религия\n- **Оранжевый** — рациональность, наука, индивидуальные достижения, модерн\n- **Зелёный** — чувствительность, равенство, экология, релятивизм, постмодерн\n- **Жёлтый** — интегративное, системное мышление, принятие сложных систем\n- **Бирюзовый** — глобальное, холистическое сознание, духовно-экологический фокус",
