    "section": "Связь эмоций и потребностей",
    "text": "**Эмоции и потребности связаны напрямую:** эмоции указывают, какие важные потребности сейчас удовлетворены, а какие нет.\n\nБазовая психологическая грамотность начинается с умения:\n1. Замечать свои чувства\n2. Переводить их на язык потребностей\n3. Заботиться о этих потребностях\n\n**Ключевой вопрос:** «Если я чувствую это, о какой моей потребности это сигнал?»",
