    "id": "basics/emotions-and-needs.md#Базовые психологические потребности",
    "title": "Эмоции и потребности",
    "sourcePath": "basics/emotions-and-needs.md",
    "section": "Базовые психологические потребности",
    "text": "### 6 групп базовых потребностей\n\n| Группа | Потребности | Примеры |\n|--------|-------------|---------|\n| **1. Безопасность и привязанность** | Быть в надёжных, тёплых отношениях | Забота, стабильность, принятие, доверие |\n| **2. Автономия и компетентность** | Ощущать, что я могу выбирать и влиять | Самостоятельность, мастерство, развитие |\n| **3. Идентичность и самоуважение** | Понимать, кто я и что для меня важно | Ценность, уникальность, самоуважение |\n| **4. Свобода выражать чувства** | Право чувствовать то, что чувствую | Быть услышанным, принятие эмоций |\n| **5. Спонтанность, игра, радость** | Возможность отдыхать, играть, пробовать | Любопытство, творчество, удовольствие |\n| **6. Любовь, принятие, принадлежность** | Быть частью «мы» | Принадлежность, любовь, принятие |\n\nКогда эти потребности долго не удовлетворяются — повышается тревога, появляется напряжение, формируются негативные убеждения о себе и мире.",
