    "text": "**Эмоциональная грамотность** — способность распознавать эмоции, понимать их источник и выражать экологично.\n\n### Четыре навыка\n\n| Навык | Вопрос для практики |\n|-------|--------------------|\n| **1. Замечать** | «Что я сейчас чувствую телом и внутри?» |\n| **2. Называть** | Подобрать слово: злость, досада, обида, тревога, усталость |\n| **3. Понимать** | «О чём это чувство, какая потребность за ним?» |\n| **4. Действовать** | Искать способ позаботиться о потребности |",
