    "id": "basics/emotions-and-needs.md#Практика: схема «эмоция → потребность → действие»",
    "title": "Эмоции и потребности",
    "sourcePath": "basics/emotions-and-needs.md",
    "section": "Практика: схема «эмоция → потребность → действие»",
    "text": "### Шаг 1: Стоп. Замечаю эмоцию\n\nСкажите себе: «Я сейчас злюсь / тревожусь / грущу». Можно начать с тела: где ощущается эмоция? Какое это ощущение?\n\n### Шаг 2: Вопрос «О какой потребности это?»\n\n| Эмоция | Вопрос | Возможная потребность |\n|--------|--------|---------------------|\n| Злость | «Что нарушено?» | Уважение, границы, справедливость |\n| Тревога | «Что неясно?» | Безопасность, опора, информация |\n| Усталость | «Чего не хватает?» | Отдых, поддержка, смысл |\n| Грусть | «Что потеряно?» | Связь, утешение, признание |\n\n### Шаг 3: Маленький шаг действия\n\n| Потребность | Возможное действие |\n|-------------|-------------------|\n| Отдых | Организовать перерыв, сон, прогулку |\n| Поддержка | Попросить помощи, позвонить близкому |\n| Границы | Сказать «нет», обозначить пределы |\n| Смысл | Вспомнить ценности, сделать что-то важное |\n| Связь | Встретиться с другом, написать, обняться |\n\nДаже один такой цикл в день уже развивает эмоциональную грамотность.",
