    "text": "**Бессознательное** — совокупность психических процессов, которые не представлены в сознании, но реально влияют на поведение и переживания.\n\n**Что хранится в бессознательном:**\n- Автоматические навыки (езда на машине «на автомате»)\n- Скрытые мотивы и вытесненные воспоминания\n- Забытые конфликты и травмы\n- Инстинкты и влечения\n\n**Как проявляется бессознательное:**\n\n| Проявление | Пример |\n|------------|--------|\n| Во сне | Сны как выражение вытесненных желаний |\n| Оговорки | «Оговорки по Фрейду» |\n| «Случайные» ошибки | Потеря ключей, опоздания |\n| Телесные симптомы | Психосоматические реакции |\n| Внезапные эмоции | Вспышки гнева без видимой причины |\n\n**Метафора:** Психика — айсберг. Сознание — маленькая надводная часть (~10%). Бессознательное — огромная подводная часть (~90%).",
