    "text": "### Формула ДА—ЧУВСТВА—ВОПРОС\n\n1. **ДА** — согласитесь с доводом оппонента\n2. **ЧУВСТВА** — обозначьте свои чувства или состояние\n3. **ВОПРОС** — задайте уточняющий вопрос для перехода к диалогу\n\n### Пример\n\n**Ситуация:** «Ты эгоист, думаешь только о себе!»\n\n**Амортизация:**\n- ДА: «Да, я часто думаю о себе, тут вы правы»\n- ЧУВСТВА: «И при этом мне важно, чтобы и тебе было хорошо»\n- ВОПРОС: «Давай обсудим, что именно тебя задело?»",
