    "id": "practices/grounding-5-4-3-2-1.md#Инструкция",
    "title": "Техника заземления 5-4-3-2-1",
    "sourcePath": "practices/grounding-5-4-3-2-1.md",
    "section": "Инструкция",
    "text": "Последовательно пройдите через пять шагов, не торопясь. На каждом шаге действительно ищите объекты — не просто вспоминайте, а смотрите, трогайте, слушайте.\n\n### 5 — Что я вижу?\n\nНайдите глазами **пять** вещей вокруг вас. Называйте их мысленно или вслух:\n\n- «Я вижу лампу на столе»\n- «Я вижу синюю кружку»\n- «Я вижу тень от стула»\n- «Я вижу свои руки»\n- «Я вижу облака за окном»\n\n### 4 — Что я могу потрогать?\n\nНайдите **четыре** вещи, к которым можете прикоснуться. Почувствуйте текстуру, температуру, вес:\n\n- Ткань одежды\n- Поверхность стола\n- Собственные волосы или кожу\n- Предмет в кармане\n\n### 3 — Что я слышу?\n\nПрислушайтесь и найдите **три** звука:\n\n- Шум вентилятора или компьютера\n- Звуки улицы за окном\n- Собственное дыхание\n\n### 2 — Что я чувствую по запаху?\n\nНайдите **два** запаха. Если ничего не чувствуете — подойдите к источнику:\n\n- Запах кофе или чая\n- Запах книги или бумаги\n- Собственный парфюм или мыло на руках\n\n### 1 — Что я чувствую на вкус?\n\nНайдите **один** вкус:\n\n- Сделайте глоток воды\n- Съешьте маленький кусочек чего-нибудь\n- Почувствуйте вкус во рту",
