    "id": "practices/nvc-4-steps.md#Пошаговая техника",
    "title": "Техника ННО: 4 шага",
    "sourcePath": "practices/nvc-4-steps.md",
    "section": "Пошаговая техника",
    "text": "Техника ННО применяется в четыре последовательных шага. Важно пройти все четыре — каждый из них выполняет свою функцию.\n\n### Шаг 1: Наблюдение\n\nОпишите факты без оценки, как если бы вы смотрели видеозапись.\n\n- ❌ «Ты всегда опаздываешь»\n- ✅ «Сегодня ты пришёл в 10:30, мы договаривались на 10:00»\n\n### Шаг 2: Чувство\n\nНазовите свою эмоцию, а не интерпретацию поведения другого.\n\n- ❌ «Я чувствую, что ты меня не уважаешь»\n- ✅ «Я чувствую раздражение и усталость»\n\n### Шаг 3: Потребность\n\nСвяжите чувство с универсальной потребностью.\n\n- ✅ «Мне важно приходить вовремя и успевать обсуждать вопросы без спешки»\n\n### Шаг 4: Просьба\n\nСформулируйте конкретную, выполнимую просьбу (не требование).\n\n- ✅ «Ты мог бы, пожалуйста, писать мне сообщение, если задерживаешься больше чем на 15 минут?»",
