    "section": "Пошаговая техника",
    "text": "### Шаг 1: Определите симптом\n\nЧто именно вас пугает? Сформулируйте конкретно: «Я боюсь, что у меня задрожат руки во время презентации».\n\n### Шаг 2: Сформулируйте парадоксальное намерение\n\nПереверните страх в желание: «Сейчас я постараюсь, чтобы мои руки задрожали как можно сильнее».\n\n### Шаг 3: Действуйте с юмором\n\nПроизнесите это вслух или про себя — с долей самоиронии. Юмор снижает напряжение и помогает дистанцироваться от страха.\n\n### Шаг 4: Наблюдайте результат\n\nКогда вы перестаёте бороться с симптомом и начинаете его «желать», тревога парадоксально снижается, а симптом часто исчезает.",
