    "section": "Практика: Духовное служение",
    "text": "### Упражнение: Служение дня\n\n**Инструкция:**\n\nКаждое утро спрашивайте:\n\n> «Кому я могу послужить сегодня? Какое доброе дело я могу сделать?»\n\n**Вечером записывайте:**\n\n```\nДата: ___________\n\n🤝 Кому я послужил(а) сегодня:\n_________________________________\n\n❤️ Какое доброе дело сделал(а):\n_________________________________\n\n🙏 За что благодарен(на) Богу/жизни:\n_________________________________\n\n🔍 Что мешало служить:\n_________________________________\n```\n\n---\n\n### Упражнение: Возвращение к детству\n\n**Инструкция:**\n\n1. Вспомните себя в возрасте 5–7 лет\n2. Что вы любили делать?\n3. Что радовало вас без причины?\n4. Что вы чувствовали перед сном?\n\n**Вопросы:**\n\n```\n👶 Что я любил(а) в детстве?\n_________________________________\n\n🎨 Что приносило радость без причины?\n_________________________________\n\n😴 Что я чувствовал(а) перед сном?\n_________________________________\n\n🔄 Что из этого я могу вернуть в свою жизнь?\n_________________________________\n```\n\n---",
