    "id": "quotes/freedom-slavery.md#Практика: Освобождение от желаний",
    "title": "quotes/freedom-slavery.md",
    "sourcePath": "quotes/freedom-slavery.md",
    "section": "Практика: Освобождение от желаний",
    "text": "### Упражнение: Карта желаний\n\n**Шаг 1:** Выпишите 10 своих главных желаний\n\n```\n1. _________________________________\n2. _________________________________\n3. _________________________________\n...\n```\n\n**Шаг 2:** Для каждого желания спросите:\n\n- Это **моё** желание или навязанное (обществом, семьёй)?\n- Это желание **освобождает** меня или **порабощает**?\n- Что будет, если я **откажусь** от этого желания?\n\n**Шаг 3:** Разделите желания на две колонки:\n\n| Освобождающие | Порабощающие |\n|--------------|--------------|\n| | |\n| | |\n\n**Шаг 4:** Выберите одно «порабощающее» желание и практикуйте отказ от него 7 дней.\n\n---\n\n### Упражнение: День свободы\n\n**Инструкция:** Один день в неделю живите по принципу:\n\n1. **Делайте только то, что действительно хотите** (не то, что «должны»)\n2. **Отказывайтесь от того, что не хотите** (вежливо, но твёрдо)\n3. **Наблюдайте**: где сопротивление, где страх, где свобода\n\n**Вечерний вопрос:**\n- Когда я чувствовал(а) себя наиболее свободным(ой)?\n- Когда я чувствовал(а) себя в «кандалах»?\n\n---",
