    "section": "Эпиктет",
    "text": "> «Лучше перестаньте говорить о независимости, так как вы зависите не только от каждого поступка окружающих вас людей, о которых вы никогда и не слыхали, но и от каждого поступка всех прошлых людей, тысячи лет тому назад превратившихся в прах.»\n\n**Контекст:** Мы все взаимосвязаны. Служение другим — служение себе.\n\n**Для размышления:** Как ваши действия влияют на других? Осознаёте ли вы эту связь?\n\n---",
