    "section": "Практика: Работа с гневом",
    "text": "### Упражнение: Карта гнева\n\n**Когда чувствуете гнев, запишите:**\n\n```\nДата: ___________\nСитуация: ___________\n\n😡 Уровень гнева (0-10): _____\n\n🎯 На кого/что направлен:\n_________________________________\n\n💭 Мои мысли в момент гнева:\n_________________________________\n\n🔍 Какая потребность нарушена:\n□ Уважение\n□ Границы\n□ Справедливость\n□ Безопасность\n□ Другое: _______\n\n🌱 Что внутри меня откликается:\n_________________________________\n\n🙏 Как я могу пожалеть (себя/другого):\n_________________________________\n\n✅ Альтернативная реакция:\n_________________________________\n```\n\n---\n\n### Упражнение: Письмо прощения\n\n**Напишите письмо тому, на кого гневаетесь (не отправляйте):**\n\n```\n[Имя],\n\nЯ гневался(ась) на тебя за _________________\n(конкретная ситуация)\n\nЯ чувствовал(а) _________________\n(эмоции: гнев, обида, боль)\n\nМоя потребность была нарушена: _________________\n\nСейчас я понимаю, что _________________\n(понимание ситуации с другой стороны)\n\nЯ прощаю тебя, потому что _________________\n(почему прощаете)\n\nЯ освобождаюсь от этого гнева.\n\nС миром,\n[Ваше имя]\n```\n\n**После написания:**\n- Зачитайте вслух\n- Порвите или сожгите (символическое освобождение)\n\n---\n\n### Упражнение: Медитация на сострадание\n\n**10 минут:**\n\n1. Закройте глаза, дышите глубоко\n2. Вспомните человека, на которого гневаете\n3. Скажите про себя:\n   - «Как и я, этот человек хочет быть счастливым»\n   - «Как и я, этот человек страдает»\n   - «Как и я, этот человек делает ошибки»\n4. Пожелайте:\n   - «Пусть ты будешь свободен от страдания»\n   - «Пусть ты найдёшь путь к миру»\n\n---",
