    "id": "quotes/memento-mori.md#Блез Паскаль",
    "title": "quotes/memento-mori.md",
    "sourcePath": "quotes/memento-mori.md",
    "section": "Блез Паскаль",
    "text": "> «Представьте себе толпу людей в цепях. Все они приговорены к смерти, и каждый день одни из них умерщвляются на глазах у других. Остающиеся, видя этих умирающих и ожидающих своей очереди, видят свою собственную участь. Такова человеческая жизнь.»\n\n**Контекст:** Мы все смертны. Осознание этого — не повод для отчаяния, а призыв к осмысленной жизни.\n\n**Для размышления:** Если бы вы знали, что умрёте через год, что бы вы изменили в своей жизни сегодня?\n\n---",
