    "id": "quotes/memento-mori.md#Лев Толстой",
    "title": "quotes/memento-mori.md",
    "sourcePath": "quotes/memento-mori.md",
    "section": "Лев Толстой",
    "text": "> «Жизнь — благо. Этот мир не шутка, не юдоль испытания и перехода в мир лучший, вечный, а этот мир, тот, в котором мы сейчас живём, — это один из вечных миров, который прекрасен, радостен и который мы не только можем, но должны нашими усилиями сделать прекраснее и радостнее для живущих с нами и для всех, которые после нас будут жить в нём.»\n\n**Контекст:** Финальное завещание Толстого. Жизнь — благо здесь и сейчас. Смерть — часть этого блага.\n\n**Для размышления:** Как вы можете сделать мир прекраснее и радостнее сегодня?\n\n---",
