    "text": "### Упражнение: Дневник мыслей\n\n**Формат:**\n\n```\nДата: ___________\nВремя: ___________\n\n📍 Ситуация:\n_________________________________\n\n💭 Автоматическая мысль:\n_________________________________\n\n😰 Эмоция (0-10):\n_________________________________\n\n🔍 Искажение мышления:\n□ Катастрофизация\n□ Чёрно-белое мышление\n□ Чтение мыслей\n□ Долженствование\n□ Другие: _______\n\n✅ Альтернативная мысль:\n_________________________________\n\n😊 Новая эмоция (0-10):\n_________________________________\n```\n\n---\n\n### Упражнение: Наблюдатель мыслей\n\n**Инструкция:**\n\n1. Сядьте удобно, закройте глаза\n2. Наблюдайте за мыслями как облака на небе\n3. Не цепляйтесь, не отталкивайте — просто наблюдайте\n4. 10–15 минут\n\n**После практики запишите:**\n\n```\n👀 Что я заметил(а):\n- Какие мысли доминируют?\n- Есть ли паттерны?\n- Какие эмоции возникают?\n\n💡 Инсайт:\n_________________________________\n```\n\n---\n\n### Упражнение: Фильтр мыслей\n\n**Каждая мысль проходит через 3 вопроса:**\n\n1. **Это правда?** (или это предположение?)\n2. **Это полезно?** (или это разрушает?)\n3. **Это добро?** (или это вредит?)\n\n**Если мысль не проходит фильтр — отпустите её.**\n\n---",
