    "text": "> «Когда определится взгляд на вещи, то будет приобретено знание; когда приобретено знание, то воля будет стремиться к правде; когда стремление воли удовлетворено, то сердце сделается добрым.»\n\n**Контекст:** Путь: взгляд → знание → воля → доброта → добродетель.\n\n**Для размышления:** На каком этапе вы? Что мешает двигаться дальше?\n\n---",
