    "title": "quotes/wisdom-knowledge.md",
    "sourcePath": "quotes/wisdom-knowledge.md",
    "section": "Браминская мудрость",
    "text": "> «Умственные занятия не могут насытить. В сад пришли два человека: учёный и живущий по Богу. Учёный сказал: \"Я знаю всё\". Живущий по Богу сказал: \"Я ничего не знаю, но я живу\"».\n\n**Контекст:** Знание ≠ жизнь. Жить — важнее, чем знать.\n\n**Для размышления:** Что для вас важнее — знать о жизни или жить?\n\n---",
