    "section": "Практика: Путь к мудрости",
    "text": "### Упражнение: Дневник незнания\n\n**Каждый день записывайте:**\n\n```\nДата: ___________\n\n❓ Что я сегодня не знаю (но думал(а), что знаю):\n_________________________________\n\n🔍 Что я узнал(а):\n_________________________________\n\n💡 Как это изменило моё понимание:\n_________________________________\n\n🙏 За что я благодарен(на) (смирение):\n_________________________________\n```\n\n---\n\n### Упражнение: Сомнение как друг\n\n**Выберите одно убеждение, в котором уверены.**\n\nЗадайте вопросы:\n\n1. **Откуда я это знаю?** (источник)\n2. **Это факт или мнение?** (проверка)\n3. **Что если это неверно?** (альтернативы)\n4. **Кто выгодал, что я в это верю?** (интересы)\n\n**Запишите ответы:**\n\n```\nУбеждение: _________________\n\n1. Источник: _________________\n2. Факт или мнение: _________\n3. Альтернативы: _____________\n4. Интересы: _________________\n\n💡 Инсайт:\n_________________________________\n```\n\n---\n\n### Упражнение: Опыт vs Теория\n\n**Составьте список:**\n\n```\n📚 Что я знаю из книг/теории:\n1. _________________________________\n2. _________________________________\n3. _________________________________\n\n🔥 Что я узнал(а) из опыта:\n1. _________________________________\n2. _________________________________\n3. _________________________________\n\n🔄 Что теория не подтвердила в опыте:\n_________________________________\n\n💡 Что опыт добавил к теории:\n_________________________________\n```\n\n---",
