    "id": "use-cases/anxiety-fears.md#Что такое тревога, страх и фобия",
    "title": "Тревога, страхи и фобии",
    "sourcePath": "use-cases/anxiety-fears.md",
    "section": "Что такое тревога, страх и фобия",
    "text": "Эти три состояния связаны, но имеют важные отличия:\n\n| Состояние | Описание | Источник |\n|-----------|----------|----------|\n| **Тревога** | Расплывчатое чувство напряжения и ожидания опасности | Без чёткого источника, «тревога обо всём» |\n| **Страх** | Реакция на конкретную угрозу | Определённый объект или ситуация |\n| **Фобия** | Навязчивый, сильный и непропорциональный страх | Конкретный триггер, избегание, потеря качества жизни |\n\n### Ключевые отличия фобии от обычного страха\n\n| Обычный страх | Фобия |\n|--------------|-------|\n| Пропорционален угрозе | Непропорционален реальной опасности |\n| Можно контролировать | Невозможно контролировать |\n| Не мешает жизни | Заставляет избегать ситуаций |\n| Проходит быстро | Длительное, стойкое состояние |",
