    "id": "use-cases/anxiety-fears.md#Причины",
    "title": "Тревога, страхи и фобии",
    "sourcePath": "use-cases/anxiety-fears.md",
    "section": "Причины",
    "text": "### Биологические факторы\n\n- Генетическая предрасположенность к повышенной тревожности\n- Особенности стресс-реакции мозга (миндалина, лимбическая система)\n- Гормоны стресса (кортизол)\n\n### Психологические факторы\n\n- Травмы детства: насилие, утраты, пренебрежение\n- Воспитание: избыточная опека, «тревожное» воспитание\n- Личностные особенности: мнительность, перфекционизм\n- Привычки: подавление чувств, повышенная ответственность\n\n### Социальные факторы\n\n- Тревожная среда и «психологическое заражение»\n- Постоянное обсуждение пугающих тем\n- Стрессовые жизненные события",
