    "id": "use-cases/anxiety-fears.md#Как формируются страхи и фобии",
    "title": "Тревога, страхи и фобии",
    "sourcePath": "use-cases/anxiety-fears.md",
    "section": "Как формируются страхи и фобии",
    "text": "1. Первый сильный испуг «привязывается» к ситуации или объекту\n2. Мозг создаёт ассоциацию («якорь»)\n3. При любом напоминании автоматически запускается тревога\n4. **Избегание** закрепляет фобию\n\n**Цикл фобии:** Триггер → Тревога → Избегание → Краткое облегчение → Закрепление.\n\nКаждый раз, когда человек «убегает от страха», он получает краткое облегчение, и мозг учится поддерживать этот цикл.",
