    "title": "Тревога, страхи и фобии",
    "sourcePath": "use-cases/anxiety-fears.md",
    "section": "Когда это становится проблемой",
    "text": "Нормальная тревога помогает ориентироваться в опасности. Признаки проблемы:\n\n- Тревога возникает слишком часто, без очевидной причины\n- Начинаете избегать обычных дел\n- Появляются телесные симптомы (одышка, тахикардия, потливость)\n- Мысли «со мной что-то серьёзно не так»\n\n### Красные флаги — срочно к специалисту\n\n- Тревога держится почти постоянно\n- Мешает работать, учиться или спать\n- Есть панические атаки\n- Страх «умереть» или «сойти с ума»\n- Выраженное избегание (перестаёте выходить из дома)\n- Мысли, что жить «нет смысла»",
