    "text": "### Изменения образа жизни\n\n| Действие | Почему помогает |\n|----------|----------------|\n| Регулярный сон | Недосып резко повышает реактивность нервной системы |\n| Физические нагрузки | Уменьшают уровень напряжения |\n| Снижение кофеина | Кофеин усиливает тревожность |\n| Снижение алкоголя | Алкоголь нарушает сон и усиливает тревогу |\n| Ограничение новостей | Постоянный поток негатива поддерживает тревогу |\n\n### Дыхательное упражнение\n\nМедленный вдох на счёт 3–5, пауза 1–2 секунды, такой же выдох на счёт 3–5. Повторить 5–10 раз.",
