    "id": "use-cases/anxiety-fears.md#Психологические методы и терапия",
    "title": "Тревога, страхи и фобии",
    "sourcePath": "use-cases/anxiety-fears.md",
    "section": "Психологические методы и терапия",
    "text": "### Когнитивно-поведенческая терапия (КПТ)\n\nНаиболее доказанный подход. В КПТ разбирают тревожные мысли, работают с катастрофическими сценариями, меняют стратегии избегания и учатся проверять реальность угрозы.\n\n### Экспозиция (для фобий)\n\nПостепенное, контролируемое приближение к пугающему стимулу: сначала в воображении, потом в реальности. Мозг «переучивается» и перестаёт запускать чрезмерную тревогу.\n\n### Парадоксальная интенция\n\nМетод Франкла: намеренное желание того, чего боишься. Страх симптома → антиципированная тревога → симптом усиливается. Парадоксальное желание → страх теряет силу → симптом ослабевает.",
