    "sourcePath": "use-cases/depression-burnout.md",
    "section": "Что такое апатия",
    "text": "**Апатия** — состояние безразличия, когда «ничего не хочется» и эмоции притуплены.\n\n| Признак | Описание |\n|---------|----------|\n| Отсутствие желаний | «Ничего не хочу, ничего не радует» |\n| Эмоциональная пустота | Эмоции притуплены, нет ни радости, ни горя |\n| Пассивность | Нет мотивации что-то делать |\n| Понимание ситуации | Человек понимает, что «надо бы», но не чувствует отклика |\n\n**Причины:** реакция на сильный стресс или утрату, длительное напряжение, болезни (дефицит B12, железа), как часть депрессии. Краткая апатия на несколько дней возможна у здорового человека. Затяжная (недели, месяцы) требует внимания специалиста.",
