    "id": "use-cases/depression-burnout.md#Что такое депрессия",
    "title": "Депрессия, апатия и выгорание",
    "sourcePath": "use-cases/depression-burnout.md",
    "section": "Что такое депрессия",
    "text": "**Депрессия** — психическое расстройство, а не просто «плохое настроение».\n\n**Диагностические критерии (минимум 2 недели):**\n- Стойко пониженное настроение **и/или**\n- Утрата интереса к тому, что раньше радовало\n\n### Частые признаки\n\n| Категория | Симптомы |\n|-----------|----------|\n| Эмоции | Печаль, чувство безнадежности, никчемности, сильной вины |\n| Энергия | Снижение энергии, быстрая утомляемость, заторможенность |\n| Сон | Бессонница или избыточный сон |\n| Аппетит | Потеря аппетита или переедание |\n| Когнитивные | Трудности с концентрацией, «туман в голове» |\n| Опасные | Навязчивые мысли о смерти или самоубийстве |\n\nДепрессия всегда требует оценки врача (психиатра или психотерапевта) и часто сочетания лекарств и психотерапии.",
