    "id": "use-cases/depression-burnout.md#Что такое эмоциональное выгорание",
    "title": "Депрессия, апатия и выгорание",
    "sourcePath": "use-cases/depression-burnout.md",
    "section": "Что такое эмоциональное выгорание",
    "text": "**Эмоциональное выгорание** — состояние истощения из-за длительного хронического стресса, чаще связанного с работой, учёбой или уходом за другими.\n\nВыгорание **«направлено» на что-то внешнее** — профессию, коллектив, сферу деятельности.\n\n| Категория | Симптомы |\n|-----------|----------|\n| Истощение | Постоянная усталость и опустошение, особенно в связи с работой |\n| Отношение к работе | Потеря интереса, раздражение, цинизм, холодность к людям |\n| Эффективность | Ощущение «никогда не успеваю», рост ошибок |\n| Физические | Ухудшение сна, внимания, психосоматические жалобы |\n\n**Важный признак:** при выгорании становится **заметно легче**, если убрать главный стрессовый фактор (например, сменить работу). При «чистой» депрессии такого не происходит.",
