    "title": "Депрессия, апатия и выгорание",
    "sourcePath": "use-cases/depression-burnout.md",
    "section": "Как различить: сравнительная таблица",
    "text": "| Критерий | Апатия | Депрессия | Выгорание |\n|----------|--------|-----------|-----------|\n| Основное чувство | «Всё безразлично» | «Всё плохо, безнадёжно» | «Я устал(а) от работы» |\n| Эмоции | Притуплены | Стойко плохие, тоска, вина | Раздражение, цинизм |\n| Интерес | Нет ни к чему | Нет к тому, что радовало | Нет к работе, но может быть к хобби |\n| Сон | Может быть в норме | Нарушен | Нарушен, мысли о работе |\n| Самооценка | В норме | Снижена, чувство никчемности | Снижена в профессиональной сфере |\n| Мысли о смерти | Нет | Часто есть | Обычно нет |\n| Облегчение при отдыхе | Временное | Нет | Да, при смене деятельности |\n\nВ реальности состояния могут наслаиваться: при выгорании появляется апатия, а длительное выгорание может перейти в депрессию.",
