    "id": "use-cases/depression-burnout.md#Что можно сделать самостоятельно",
    "title": "Депрессия, апатия и выгорание",
    "sourcePath": "use-cases/depression-burnout.md",
    "section": "Что можно сделать самостоятельно",
    "text": "### Сон, питание, движение\n\n- Наладить режим сна — сон критичен для восстановления психики\n- Регулярно есть — низкий сахар усиливает тревогу и апатию\n- Физическая активность — даже короткие прогулки поддерживают состояние\n\n### Маленькие шаги вместо рывков\n\nРазбивать задачи на микрошаги, хвалить себя за малейший прогресс. Вместо «убрать всю квартиру» → «протереть один стол».\n\n### Границы и отдых\n\nУменьшать сверхнагрузку, учиться говорить «нет», брать реальные перерывы, отделять время работы от отдыха.\n\n### Социальная поддержка\n\nОбщаться с теми, кто относится с пониманием. Избегать тех, кто обесценивает («соберись», «перестань ныть»). Просить помощи, когда нужно.",
